    public function store(Request $request): \Illuminate\Http\JsonResponse
    {
        try {
            $validateRequest = Validator::make($request->all(), [
                'booking_id' => 'required|integer',
                'ticket_status_id' => 'required|integer',
            ]);

            if ($validateRequest->fails()) {
                return response()->json(['error' => $validateRequest->errors()], 400);
            }

            $userId = auth()->id();

            $createTicketQuery = Ticket::query()->create([
                'booking_id' => $request->get('booking_id'),
                'ticket_status_id' => $request->get('ticket_status_id'),
                'user_id' => $userId,
                'qr_code_text' => "",
            ]);
            $responseQueryAfterCreateTicket =  Ticket::with('booking.event')
                ->where('ticket_id', $createTicketQuery->ticket_id)
                ->first();
//                Ticket::with('booking.event')->find($createTicketQuery->id);
            Log::warning("hhehehe $responseQueryAfterCreateTicket");
            return response()->json([
                'status_code' => 201,
                'message' => 'Ticket Created',
                'data' =>$responseQueryAfterCreateTicket ?? null
            ], 201);

        } catch (\Illuminate\Database\QueryException $e) {
            // Database specific errors
            \Log::error('Database Error in Ticket Creation: ' . $e->getMessage(), [
                'user_id' => auth()->id(),
                'request_data' => $request->all(),
                'sql_code' => $e->getCode(),
                'trace' => $e->getTraceAsString()
            ]);

            return response()->json([
                'error' => 'Database error occurred while creating ticket',
                'message' =>$e->getMessage()
            ], 500);

        } catch (\Illuminate\Validation\ValidationException $e) {
            // Validation errors (though this should be caught earlier)
            \Log::error('Validation Error in Ticket Creation: ' . $e->getMessage());

            return response()->json([
                'error' => 'Validation failed',
                'details' => $e->errors()
            ], 422);

        } catch (\Exception $e) {
            // General exceptions
            \Log::error('General Error in Ticket Creation: ' . $e->getMessage(), [
                'user_id' => auth()->id(),
                'request_data' => $request->all(),
                'file' => $e->getFile(),
                'line' => $e->getLine(),
                'trace' => $e->getTraceAsString()
            ]);

            return response()->json([
                'error' => 'An unexpected error occurred',
                'message' => 'Please try again later'
            ], 500);
        }
    }

